name: PR Title

on:
  pull_request_target:
    types: [opened, edited, synchronize, reopened, ready_for_review]

permissions:
  pull-requests: read

concurrency:
  group: pr-title-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  check-pr-title:
    name: Check PR title
    runs-on: ubuntu-latest
    steps:
      # Read metadata only; never check out or execute code from the PR.
      - name: Validate PR title
        uses: actions/github-script@v8
        with:
          script: |
            // Fetch the current title so reruns also reflect title edits.
            const { data: pr } = await github.rest.pulls.get({
              ...context.repo,
              pull_number: context.issue.number,
            });
            const types = ['Feat', 'Fix', 'Refactor', 'Perf', 'Doc', 'Test', 'CI', 'Chore'];
            const pattern = new RegExp(
              String.raw`^\[(${types.join('|')})\] (?:\[([A-Za-z0-9][A-Za-z0-9._+-]*)\] )?` +
              String.raw`[A-Za-z0-9]+(?:[._/-][A-Za-z0-9]+)*: \S(?:[^\r\n]*\S)?$`
            );
            const match = pattern.exec(pr.title);
            const hardware = match?.[2];
            // Hardware is uppercase except for these four canonical brand spellings.
            const brands = ['Intel', 'Apple', 'Huawei', 'Ascend'];
            const brand = brands.find(name => name.toLowerCase() === hardware?.toLowerCase());
            const validHardware = !hardware || hardware === (brand || hardware.toUpperCase());
            // Preserve GitHub's generated revert titles, including legacy originals.
            const isRevert = /^Revert "\S(?:[^\r\n]*\S)?"$/.test(pr.title);
            if ((!(match && validHardware) && !isRevert) || pr.title !== pr.title.trim()) {
              core.setFailed(
                'PR title must use "[Type] scope: title" or "[Type] [Hardware] scope: title". ' +
                `Type must be one of: ${types.join(', ')}. ` +
                'Scope is required and may be any module or model name, with unrestricted letter case ' +
                '(letters, numbers, dots, underscores, slashes, or hyphens). ' +
                'Hardware is optional; use a single tag without spaces. Use uppercase hardware tags (AMD, NVIDIA, NPU, MI300X), except for exactly these four spellings: Intel, Apple, Huawei, Ascend. ' +
                'Reverts must use GitHub\'s default format: Revert "original title". ' +
                'Use one space between fields and after the colon, with a non-empty title ' +
                'and no leading or trailing whitespace. ' +
                'Examples: "[Fix] attention: Fix KV cache indexing", ' +
                '"[Feat] qwen3: Add model support", ' +
                '"[Perf] [AMD] flash-attn: Optimize decode performance".'
              );
            }

"""The GLM-5.3-Flash gfx950 layer launch on random weights in SGLang's layouts
(RFC #43949), under torchrun at TP2, TP4 and TP8 (``glm53_flash/check_layer.py``):
each launch kind finishes on every rank with no error word and the same output,
and writes exactly its valid rows' state or cache rows (none of a pad row's); a
sparse-attention launch on AITER-shuffled FP8 projections equals the row-major one
bitwise."""

import subprocess
import sys
import unittest
from pathlib import Path

import torch
from sglang.test.test_utils import CustomTestCase


def _gfx950_gpus() -> int:
    if not (torch.cuda.is_available() and torch.version.hip):
        return 0
    if "gfx950" not in torch.cuda.get_device_properties(0).gcnArchName:
        return 0
    return torch.cuda.device_count()


CHECK = Path(__file__).with_name("glm53_flash") / "check_layer.py"


@unittest.skipIf(_gfx950_gpus() < 8, "needs 8 gfx950 GPUs")
class TestMonoGlm53FlashKernels(CustomTestCase):
    def _check(self, *args: str) -> None:
        for tp in (2, 4, 8):
            cmd = [
                sys.executable,
                "-m",
                "torch.distributed.run",
                f"--nproc-per-node={tp}",
                f"--master-port={29610 + tp}",
                str(CHECK),
                *args,
            ]
            result = subprocess.run(cmd, timeout=1800)
            self.assertEqual(result.returncode, 0, f"{' '.join(args)} at TP{tp}")

    def test_each_launch_kind(self):
        # 4 rows (TP2 builds no wider launch), the last a pad row
        for kind in ("ffn", "kda", "dsa"):
            self._check("--kind", kind, "--rows", "4", "--pad-rows", "1", "--writes")

    def test_shuffled_fp8_projections_match_row_major(self):
        self._check("--kind", "dsa", "--rows", "4", "--compare-shuffled")


if __name__ == "__main__":
    unittest.main()

"""The DeepSeek-V4.1 gfx950 monokernels against SGLang's ops (RFC #43949), each
check under torchrun at TP2 and TP4 (``deepseek_v41/check_*.py``): K1's seam
mixes, SWA KV records and query; K2's attention core, wo_a and wo_b stages; the
FFN launch's seam, norm and MoE, on the target's route and the DSpark draft's;
each output against the spec's bound, then a bitwise graph replay across widths
with every rank agreeing."""

import subprocess
import sys
import unittest
from pathlib import Path

import torch
from sglang.test.test_utils import CustomTestCase


def _gfx950_gpus() -> int:
    if not (torch.cuda.is_available() and torch.version.hip):
        return 0
    if "gfx950" not in torch.cuda.get_device_properties(0).gcnArchName:
        return 0
    return torch.cuda.device_count()


CHECKS = Path(__file__).with_name("deepseek_v41")


@unittest.skipIf(_gfx950_gpus() < 4, "needs 4 gfx950 GPUs")
class TestMonoDeepseekV41Kernels(CustomTestCase):
    def _check(self, module: str, *args: str) -> None:
        for tp in (2, 4):
            cmd = [
                sys.executable,
                "-m",
                "torch.distributed.run",
                f"--nproc-per-node={tp}",
                f"--master-port={29600 + tp}",
                str(CHECKS / f"{module}.py"),
                *args,
            ]
            result = subprocess.run(cmd, timeout=1800)
            self.assertEqual(result.returncode, 0, f"{module} at TP{tp}")

    def test_ffn_launch(self):
        self._check("check_ffn", "--replays", "200")

    def test_ffn_launch_draft_route(self):
        # the DSpark draft's MoE: 128 experts, top-3, a FP4 group an ug task
        self._check("check_ffn", "--replays", "100", "--draft")

    def test_k1(self):
        self._check("check_k1", "--trials", "2")

    def test_k2(self):
        self._check("check_k2", "--replays", "100")


if __name__ == "__main__":
    unittest.main()

"""The SGLang names this package reads (RFC #43949), pinned on CPU against the
installed SGLang.

The specs and kernels live outside SGLang, so they read SGLang by name: the
monokernel framework (``sglang.srt.monokernels``) and SGLang internals.
Every module that imports from ``sglang`` lists what it reads in
``SGLANG_READS``. A refactor that renames one fails here, naming the file to
repair, instead of failing at a GPU server's startup. The checks are static
(AST): no module of this package is imported. Run it against each SGLang this
package supports, and nightly against SGLang main.
"""

import ast
from functools import lru_cache
from pathlib import Path

import pytest
import sglang

import sgl_amd_mono

ROOT = Path(sglang.__file__).resolve().parent  # the installed sglang package
PACKAGE = Path(sgl_amd_mono.__file__).resolve().parent


@lru_cache(maxsize=None)
def _tree(path: Path) -> ast.Module:
    return ast.parse(path.read_text())


@lru_cache(maxsize=None)
def _provided(path: Path) -> frozenset:
    """What a source file provides: definitions, assignment targets (``x.name = ...``
    too), imported names, parameters as ``f(p)`` and string literals as ``"x"``."""
    names = set()
    for node in ast.walk(_tree(path)):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
            if not isinstance(node, ast.ClassDef):
                params = node.args.posonlyargs + node.args.args + node.args.kwonlyargs
                names.update(f"{node.name}({p.arg})" for p in params)
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for target in targets:
                for t in ast.walk(target):
                    if isinstance(t, ast.Name):
                        names.add(t.id)
                    elif isinstance(t, ast.Attribute):
                        names.add(t.attr)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            names.update((a.asname or a.name).split(".")[0] for a in node.names)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            names.add(f'"{node.value}"')
    return frozenset(names)


def _declared(path: Path) -> dict:
    """The module's ``SGLANG_READS``, or {} without one."""
    for node in _tree(path).body:
        if isinstance(node, ast.Assign) and any(
            isinstance(t, ast.Name) and t.id == "SGLANG_READS" for t in node.targets
        ):
            return ast.literal_eval(node.value)
    return {}


def _sglang_imports(path: Path) -> set:
    return {
        a.asname or a.name
        for node in ast.walk(_tree(path))
        if isinstance(node, ast.ImportFrom)
        and (node.module or "").startswith("sglang.")
        for a in node.names
    }


READERS = [
    p for p in sorted(PACKAGE.rglob("*.py")) if _declared(p) or _sglang_imports(p)
]


def _id(path: Path) -> str:
    return str(path.relative_to(PACKAGE.parent))


@pytest.mark.parametrize("path", READERS, ids=_id)
def test_every_sglang_import_is_declared(path):
    declared = {n for names in _declared(path).values() for n in names}
    undeclared = _sglang_imports(path) - declared
    assert not undeclared, f"{_id(path)}: declare {sorted(undeclared)} in SGLANG_READS"


@pytest.mark.parametrize("path", READERS, ids=_id)
def test_sglang_provides_what_the_plugin_reads(path):
    missing = []
    for pattern, names in _declared(path).items():
        files = sorted(ROOT.glob(pattern))
        assert files, f"{_id(path)}: no file matches {pattern}"
        provided = frozenset().union(*map(_provided, files))
        missing += [f"{pattern}: {n}" for n in names if n not in provided]
    assert not missing, (
        f"SGLang no longer provides what {_id(path)} reads; repair it and its "
        "SGLANG_READS:\n  " + "\n  ".join(missing)
    )

"""GLM-5.3-Flash with --monokernel-backend amd on MI35x, TP4 (RFC #43949), across the
switch points: decode steps of 1 to 8 rows run the kernels, wider ones the normal
path, and requests join and leave a running batch that steps past 8 rows and back
(a short GSM8K run, for gross failures); the tokens of covered steps scored again by
the normal prefill path (KL consistency); each covered layer against SGLang's own
under SGLANG_AMD_MONO_CHECK; and a fault on one rank that stops the server before
any token of the failed step is sent."""

import os
import re
import tempfile
import time
import unittest
from types import SimpleNamespace

import requests
from glm53_flash_server import ARGS, ENV, MODEL
from sglang.test.kl_test_utils import (
    test_input_output_logprobs_match_helper as assert_logprobs_match,
)
from sglang.test.sgl_eval_utils import run_sgl_eval
from sglang.test.test_utils import (
    DEFAULT_URL_FOR_TEST,
    CustomTestCase,
    popen_launch_server,
    terminate_and_kill_process_tree,
)

from sgl_amd_mono import BACKEND

LAUNCH_TIMEOUT = 3600
# The normal path scores about 0.97 on GSM8K (thinking on); the bound is for gross
# failures
GSM8K_BOUND = 0.90
# Decode against prefill, one batch of prompts at a time (every decode step covered);
# the normal path itself averages about 0.04 on 8 prompts
KL_BOUND = 0.06


def _launch(extra_env=None, extra_args=(), log=None):
    env = {**os.environ, **ENV, **(extra_env or {})}
    return popen_launch_server(
        MODEL,
        DEFAULT_URL_FOR_TEST,
        timeout=LAUNCH_TIMEOUT,
        other_args=ARGS + ["--monokernel-backend", BACKEND, *extra_args],
        env=env,
        return_stdout_stderr=log,
    )


class TestMonokernelDecode(CustomTestCase):
    @classmethod
    def setUpClass(cls):
        cls.process = _launch(extra_args=["--watchdog-timeout", "600"])

    @classmethod
    def tearDownClass(cls):
        if getattr(cls, "process", None) is not None:
            terminate_and_kill_process_tree(cls.process)

    def test_gsm8k_past_the_largest_width(self):
        # 12 requests at a time: the batch steps past 8 rows as it fills, and back
        # as it drains
        metrics = run_sgl_eval(
            SimpleNamespace(
                base_url=DEFAULT_URL_FOR_TEST,
                model=MODEL,
                eval_name="gsm8k",
                num_examples=200,
                num_threads=12,
                max_tokens=32768,
                temperature=1.0,
                top_p=0.95,
                seed=42,
                sgl_eval_thinking=True,
            )
        )
        print(f"{metrics=}")
        self.assertGreater(metrics["score"], GSM8K_BOUND)

    def test_covered_steps_match_prefill(self):
        # one graph per batch (ignore_eos keeps its rows): 2, 3, 7 and 8 rows (widths
        # 2, 4 and 8, pad rows at 3 and 7). Each graph reads its own metadata buffers;
        # with the cache flushed, a graph replayed first on another's reads none of
        # this batch's pages
        for rows in (2, 3, 7, 8):
            requests.post(DEFAULT_URL_FOR_TEST + "/flush_cache").raise_for_status()
            assert_logprobs_match(
                DEFAULT_URL_FOR_TEST,
                {MODEL: {"kl_div": KL_BOUND}},
                MODEL,
                max_samples=rows,
                max_new_tokens=512,
                trust_remote_code=True,
            )


class TestMonokernelCheck(CustomTestCase):
    def test_each_covered_layer_within_its_numerics(self):
        # SGLANG_AMD_MONO_CHECK (eager) runs the normal layer next to each covered layer; 1, 3
        # and 8 rows run at widths 2, 4 and 8 (pad rows on the first two), and the
        # long prompt's positions pass 2048, where the sparse attention selects keys
        para = "The river valley archive lists the flood height of every year. "
        with (
            tempfile.NamedTemporaryFile("w+", suffix=".out") as out,
            tempfile.NamedTemporaryFile("w+", suffix=".err") as err,
        ):
            process = _launch(
                extra_env={"SGLANG_AMD_MONO_CHECK": "1"},
                extra_args=["--disable-cuda-graph"],
                log=(out, err),
            )
            try:
                for n, repeats in ((1, 2), (3, 2), (8, 2), (1, 200)):
                    r = requests.post(
                        DEFAULT_URL_FOR_TEST + "/generate",
                        json={
                            "text": [
                                f"Record {i}. " + para * repeats for i in range(n)
                            ],
                            "sampling_params": {"max_new_tokens": 4, "temperature": 0},
                        },
                        timeout=600,
                    )
                    r.raise_for_status()
            finally:
                terminate_and_kill_process_tree(process)
            err.seek(0)
            out.seek(0)
            log = err.read() + out.read()
        checks = re.findall(
            r"monokernel check layer \d+ \((kda|dsa), (\d+) rows, positions "
            r"\d+\.\.(\d+)\): (.*)",
            log,
        )
        values = {}
        for _, _, _, fields in checks:
            for name, v in re.findall(r"(\S+)=(\S+)", fields):
                values.setdefault(name, []).append(float(v))
        for name, vs in sorted(values.items()):
            print(f"{name}: min {min(vs):.6g} max {max(vs):.6g} ({len(vs)} checks)")
        seen = {(kind, int(rows)) for kind, rows, _, _ in checks}
        want = {(kind, rows) for kind in ("kda", "dsa") for rows in (1, 3, 8)}
        self.assertTrue(want <= seen, seen)
        self.assertTrue(any(k == "dsa" and int(hi) >= 2048 for k, _, hi, _ in checks))
        violations = re.findall(r"monokernel check violation: .*", log)
        self.assertEqual(violations, [], "\n".join(violations[:20]))


class TestMonokernelFault(CustomTestCase):
    def test_a_stalled_rank_stops_the_server_without_tokens(self):
        # past the warmup (20 steps of a width), rank 1 stalls at its first wait;
        # at the deadline (half the watchdog) it stops, and its peers stop on its flag
        with (
            tempfile.NamedTemporaryFile("w+", suffix=".out") as out,
            tempfile.NamedTemporaryFile("w+", suffix=".err") as err,
        ):
            process = _launch(
                extra_env={"SGLANG_AMD_MONO_FAULT_INJECT": "1:1:20"},
                extra_args=["--watchdog-timeout", "20"],
                log=(out, err),
            )
            try:
                texts = []

                def generate():
                    r = requests.post(
                        DEFAULT_URL_FOR_TEST + "/generate",
                        json={
                            "text": ["Write a long essay about lighthouses."] * 2,
                            "sampling_params": {
                                "max_new_tokens": 1024,
                                "temperature": 0,
                                "ignore_eos": True,
                            },
                        },
                        timeout=300,
                    )
                    if r.status_code == 200:
                        texts.extend(item.get("text") for item in r.json())

                try:
                    generate()
                except requests.RequestException:
                    pass
                self.assertFalse(
                    any(texts), "a failed step's tokens reached the client"
                )
                deadline = time.time() + 300
                while process.poll() is None and time.time() < deadline:
                    time.sleep(2)
                self.assertIsNotNone(process.poll(), "the server kept running")
                err.seek(0)
                out.seek(0)
                log = err.read() + out.read()
                # a launch never runs on after a failed wait: it stops with a store
                # to the null page, so the only faults are at address 0x0
                faults = re.findall(r"faulting addr: (0x[0-9a-fA-F]+)", log)
                self.assertTrue(faults, log[-2000:])
                self.assertEqual(set(faults) - {"0x0"}, set(), faults)
            finally:
                terminate_and_kill_process_tree(process)


if __name__ == "__main__":
    unittest.main()

"""The kernels' cache key: every FlyDSL launcher closes over its module's import-time
sources digest and every build parameter, and the digest follows what the module
imports."""

import ast
import functools
import sys
import types
from pathlib import Path

import sgl_amd_mono
from sgl_amd_mono.common import plan

PACKAGE = Path(sgl_amd_mono.__file__).resolve().parent


def _flyc(fn: ast.FunctionDef, kind: str) -> bool:
    """Whether ``fn`` is decorated ``@flyc.<kind>`` (``jit``, or ``kernel(...)``)."""
    for d in fn.decorator_list:
        d = d.func if isinstance(d, ast.Call) else d
        if (
            isinstance(d, ast.Attribute)
            and d.attr == kind
            and isinstance(d.value, ast.Name)
            and d.value.id == "flyc"
        ):
            return True
    return False


def _reads(node: ast.AST) -> set:
    return {
        n.id
        for n in ast.walk(node)
        if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)
    }


def _digests_at_import(tree: ast.Module) -> bool:
    """Whether the module assigns ``SOURCES = kernel_sources(__name__)`` at import."""
    return any(
        isinstance(n, ast.Assign)
        and [getattr(t, "id", None) for t in n.targets] == ["SOURCES"]
        and isinstance(n.value, ast.Call)
        and getattr(n.value.func, "id", None) == "kernel_sources"
        and [getattr(a, "id", None) for a in n.value.args] == ["__name__"]
        for n in tree.body
    )


def _keys_the_build(builder: ast.FunctionDef) -> bool:
    """Whether ``builder`` assigns ``keyed`` from ``SOURCES`` and each of its
    parameters, or its whole ``locals()``."""
    params = {a.arg for a in builder.args.args + builder.args.kwonlyargs}
    for n in ast.walk(builder):
        if isinstance(n, ast.Assign) and any(
            getattr(t, "id", None) == "keyed" for t in n.targets
        ):
            reads = _reads(n.value)
            if "SOURCES" in reads and ("locals" in reads or params <= reads):
                return True
    return False


def _launchers():
    """Each ``@flyc.jit`` that launches a kernel, with whether it closes over a
    ``keyed`` that holds its module's import-time digest and every build parameter
    (itself or through a kernel it calls)."""
    for path in sorted(PACKAGE.rglob("*.py")):
        tree = ast.parse(path.read_text())
        parent = {c: n for n in ast.walk(tree) for c in ast.iter_child_nodes(n)}
        for fn in ast.walk(tree):
            if not (isinstance(fn, ast.FunctionDef) and _flyc(fn, "jit")):
                continue
            # Device helpers also use @flyc.jit; the enclosing launcher owns
            # their transitive source digest.
            if not any(
                isinstance(n, ast.Call)
                and isinstance(n.func, ast.Attribute)
                and n.func.attr == "launch"
                for n in ast.walk(fn)
            ):
                continue
            builder = parent.get(fn)
            while builder is not None and not isinstance(builder, ast.FunctionDef):
                builder = parent.get(builder)
            name = f"{path.relative_to(PACKAGE)}:{fn.lineno} {fn.name}"
            if builder is None:
                yield name, False
                continue
            keyed_kernels = {
                f.name
                for f in ast.walk(builder)
                if isinstance(f, ast.FunctionDef)
                and _flyc(f, "kernel")
                and "keyed" in _reads(f)
            }
            reads = _reads(fn)
            yield (
                name,
                (
                    _digests_at_import(tree)
                    and _keys_the_build(builder)
                    and ("keyed" in reads or bool(reads & keyed_kernels))
                ),
            )


def test_every_launcher_closes_over_the_sources_digest():
    # FlyDSL keys a launcher on its closure's scalars and same-directory helpers only,
    # so one missing the digest or a build parameter keeps serving stale kernels
    launchers = dict(_launchers())
    assert launchers, "found no @flyc.jit launcher"
    missing = sorted(name for name, ok in launchers.items() if not ok)
    assert not missing, (
        "close over `keyed` built from the module's `SOURCES = kernel_sources(__name__)`"
        f" and every build parameter: {missing}"
    )


def test_the_digest_follows_the_code_the_kernel_module_imports(tmp_path, monkeypatch):
    # FlyDSL's own key ignores modules outside the kernel's directory, so without
    # this a persistent cache would serve kernels traced against old helpers
    plugin, aiter = tmp_path / "sgl_amd_mono", tmp_path / "kernels"
    model = plugin / "model"
    for d in (model, aiter):
        d.mkdir(parents=True)
    for package, root in (
        (plugin, "sgl_amd_mono"),
        (aiter, "aiter.ops.flydsl.kernels"),
    ):
        (package / "__init__.py").write_text("")
        module = types.ModuleType(root)
        module.__file__ = str(package / "__init__.py")
        monkeypatch.setitem(sys.modules, root, module)
    (model / "__init__.py").write_text("")
    (model / "kernel.py").write_text(
        "from aiter.ops.flydsl.kernels import buffer_ops as bo\n"
        "from aiter.ops.flydsl.kernels.dpp import shuffle\n"
        "import sgl_amd_mono.model.layout\n"
        "def build():\n"
        "    from ..model.tiles import TILE\n"
    )
    for cached in ("_module_code", "kernel_sources"):
        monkeypatch.setattr(
            plan, cached, functools.cache(getattr(plan, cached).__wrapped__)
        )

    def digest():
        plan._module_code.cache_clear()
        plan.kernel_sources.cache_clear()
        return plan.kernel_sources("sgl_amd_mono.model.kernel")

    edits = {
        aiter / "buffer_ops.py": "A = 1\n",
        aiter / "dpp.py": "def shuffle():\n    return 1\n",
        model / "layout.py": "B = 1\n",
        model / "tiles.py": "TILE = 1\n",
        model / "runner.py": "C = 1\n",
    }
    for f, text in edits.items():
        f.write_text(text)
    before = digest()
    (model / "runner.py").write_text("C = 2\n")
    (model / "layout.py").write_text('"""Doc."""\nB = 1  # a comment\n')
    assert digest() == before, "an unimported module or a comment changed the key"
    for f, text in edits.items():
        if f.name != "runner.py":
            f.write_text(text.replace("1", "2"))
            assert digest() != before, f"an edit to imported {f.name} kept the key"
            f.write_text(text)
